-- Runs under the CURRENT version on a save made by an old one: after a game-minute, the base works.
-- A fingerprint of the hidden world (every Tier 1 response on gears and circuits, family chemistry): written by the old
-- version and by the new one after loading; upgrade_test.sh compares them (a world must never be
-- regenerated by an upgrade).
local function truth_fingerprint()
  local ok, t = pcall(remote.call, "empirical-science", "truth")
  if not (ok and t and t.targets) then return nil end
  local lines = {}
  for _, key in ipairs({"gear", "circuit"}) do
    for _, a in ipairs({"coal", "wood", "stone", "stone-brick", "copper-cable"}) do
      local r = t.targets[key] and t.targets[key][a]
      if r then table.insert(lines, string.format("%s %s %s %.9f %.9f %.9f", key, a, tostring(r.kind), r.peak or 0, r.opt or 0, r.score or 0)) end
    end
  end
  -- Drawn after the targets in a fresh world: a regeneration shows here first (family chemistry).
  local fams = {}
  for fam in pairs(t.chem or {}) do table.insert(fams, fam) end
  table.sort(fams)
  for _, fam in ipairs(fams) do table.insert(lines, string.format("chem %s %.9f", fam, t.chem[fam])) end
  if t.responsiveness and t.responsiveness.gear then
    table.insert(lines, string.format("responsiveness gear %.9f", t.responsiveness.gear))
  end
  return table.concat(lines, "\n") .. "\n"
end

-- (0.72) The station shrank to its layout: packs in an old station's slots past the new size are lost at
-- load, before any script runs (accepted: the mod was unpublished). Recorded, and packs given back
-- so the old samples can still be read.
-- (A tick after load: in on_init the mod's own migration has not refiltered the slots yet, and the insert failed.)
script.on_nth_tick(60, function()
  if storage.packs_after_load then return end
  local s = game.surfaces[1]
  local station = s.find_entities_filtered{name = "es-analysis-station"}[1]
  if not station then return end
  local inv = station.get_inventory(defines.inventory.chest)
  storage.packs_after_load = inv.get_item_count("automation-science-pack")
  if storage.packs_after_load == 0 then inv.insert{name = "automation-science-pack", count = 20} end
end)
script.on_nth_tick(3600, function(event)
  if event.tick == 0 then return end
  local fp = truth_fingerprint()
  if fp then helpers.write_file("es-truth-after.txt", fp) end
  local s = game.surfaces.nauvis
  local lines, failed = {}, 0
  local function check(name, ok, detail)
    if not ok then failed = failed + 1 end
    table.insert(lines, (ok and "PASS " or "FAIL ") .. name .. (detail ~= nil and ("  " .. tostring(detail)) or ""))
  end
  local station = s.find_entities_filtered{name = "es-analysis-station"}[1]
  local st = station and remote.call("empirical-science", "station", station.unit_number, "gear")
  check("station known to the new version", st ~= nil)
  -- (0.72) Science richness, a layer the old world did not have, is added on load: one value per process class.
  local ok_t, tr = pcall(remote.call, "empirical-science", "truth")
  local n_rich = 0
  for _ in pairs(ok_t and tr and tr.richness or {}) do n_rich = n_rich + 1 end
  check("science richness added to an old world, one value per process class", n_rich == 3, n_rich)
  -- 0.72: samples from before are their tier's item now; none of the old item is left in the station.
  if station then
    local inv = station.get_inventory(defines.inventory.chest)
    local old, new = inv.get_item_count("es-sample"), inv.get_item_count("es-sample-automation-science-pack")
    local migrated = remote.call("empirical-science", "samples_migrated")
    -- (A version from after 0.72's tiering has nothing to migrate: the four its waiting slots took are read or waiting.)
    check("old samples became their tier's sample (none of the old item left)",
      old == 0 and (migrated >= 6 or (migrated == 0 and new + (st and st.analysed or 0) >= 4)),
      string.format("old %d, migrated %d, red %d, analysed %d", old, migrated, new, st and st.analysed or -1))
  end
  local held = {}
  if station then
    local inv = station.get_inventory(defines.inventory.chest)
    for i = 1, #inv do
      local f = inv.get_filter(i)
      table.insert(held, i .. ":" .. (inv[i].valid_for_read and (inv[i].name .. "x" .. inv[i].count) or "-")
        .. (f and ("[" .. f.name .. "]") or ""))
    end
  end
  check("old samples analysed (or discarded as unreadable, never crashing)", st and st.analysed + st.unreadable >= 1,
    st and string.format("analysed %d, unreadable %d (red packs left after load %s); slots %s", st.analysed, st.unreadable,
      tostring(storage.packs_after_load), table.concat(held, " ")))
  -- The setup inserts samples whose yield is a product count (the pre-0.5 format, 11 to 16 gears):
  -- they must be read as 110-160% of nominal, not as about -90%.
  local s_ctrl = st and st.summaries.control
  check("old count-format samples converted", s_ctrl and s_ctrl.n > 0 and s_ctrl.mean > 0,
    s_ctrl and string.format("control n=%d mean %.0f per mille", s_ctrl.n, s_ctrl.mean or 0))
  local crafted = 0
  for _, b in pairs(s.find_entities_filtered{name = "es-test-bench"}) do crafted = crafted + b.products_finished end
  check("benches still craft", crafted > 0, crafted)
  -- 0.14 replaced adoption recipes and the scripted buildings by dosing: they are gone without a
  -- trace (their entities removed with their prototypes), and a dose works on the upgraded save.
  local leftovers = 0
  for _, name in ipairs({"es-advanced-bench", "es-formulation-plant", "es-advanced-fluid-port", "es-advanced-power",
      "es-advanced-control"}) do
    if prototypes.entity[name] then leftovers = leftovers + #s.find_entities_filtered{name = name} end
  end
  check("old scripted buildings and their parts are gone", leftovers == 0, leftovers)
  local asm = s.find_entities_filtered{name = "assembling-machine-2", position = {30.5, 0.5}, radius = 1}[1]
  if asm then
    local r = asm.get_recipe()
    check("an assembler that ran an old adoption recipe has none now (or a vanilla one)",
      not r or not r.name:find("^es%-catalysed%-"), r and r.name)
  end
  local m = s.create_entity{name = "assembling-machine-2", position = {40.5, 20.5}, force = "player", raise_built = true}
  m.set_recipe("iron-gear-wheel")
  remote.call("empirical-science", "set_dose", m.unit_number, {rows = {{name = "stone", dose = 5}}})
  check("a machine can be dosed on the upgraded save", remote.call("empirical-science", "dose_state", m.unit_number).mix ~= nil)
  -- Staged reveal (0.32): a save from before keeps every staged tool (stage techs researched; a second
  -- row and circuit mode still dose).
  m.set_recipe("iron-gear-wheel")
  remote.call("empirical-science", "set_dose", m.unit_number, {rows = {{name = "stone", dose = 5}, {name = "coal", dose = 2}}})
  local mix = remote.call("empirical-science", "dose_state", m.unit_number).mix or {}
  local techs, recipes = game.forces.player.technologies, game.forces.player.recipes
  -- (0.72: alternative recipes are retired, their technology and recipes with them.)
  check("a save from before staging keeps every staged tool, and alternative recipes are gone",
    techs["es-mixtures"].researched and techs["es-thermal-studies"].researched and mix.coal == 2
      and techs["es-process-routes"] == nil and recipes["es-route-gear-cast"] == nil,
    string.format("mixtures %s, thermal %s, second row %s, routes technology %s, cast gear recipe %s",
      tostring(techs["es-mixtures"].researched), tostring(techs["es-thermal-studies"].researched), tostring(mix.coal),
      tostring(techs["es-process-routes"] ~= nil), tostring(recipes["es-route-gear-cast"] ~= nil)))
  -- Residues by family (0.39): stone brick's residue and catalyst became stone's (gravel, activated silica).
  local rcs = s.find_entities_filtered{name = "steel-chest", position = {-20.5, -20.5}, radius = 0.6}
  if rcs[1] then
    local inv = rcs[1].get_inventory(defines.inventory.chest)
    local marker = inv.get_item_count("copper-plate")
    local want_res, want_cat = marker % 2 == 1 and 20 or 0, marker >= 2 and 20 or 0
    local res, cat = inv.get_item_count("es-spent-stone"), inv.get_item_count("es-refined-stone")
    check("old stone brick residue and catalyst became the mineral family's", res == want_res and cat == want_cat,
      string.format("gravel %d (want %d), activated silica %d (want %d)", res, want_res, cat, want_cat))
  end
  -- Residues leave by the machine (0.65): no exhaust hopper is left (0.71: its prototype is gone), and an
  -- old hopper has no bar.
  if s.find_entities_filtered{name = "wooden-chest", position = {-24.5, -23.5}, radius = 0.6}[1] then
    local left = prototypes.entity["es-exhaust-hopper"] and #s.find_entities_filtered{name = "es-exhaust-hopper"} or 0
    local hop = s.find_entities_filtered{name = "es-hopper", position = {-28.5, -20.5}, radius = 0.6}[1]
    local hinv = hop and hop.get_inventory(defines.inventory.chest)
    check("no exhaust hopper is left; old hoppers lost their bar", left == 0 and hinv and hinv.get_bar() == #hinv + 1,
      string.format("exhausts left %d, hopper bar %s of %s", left, tostring(hinv and hinv.get_bar()), tostring(hinv and #hinv)))
  end
  -- (0.71) Hoppers lose their overlaid fluid port and its fluid (user: the fluid hopper, a 1x2 pump, may not fit
  -- an old hopper's tile): both stay hoppers, the mixed one keeps its items; no port is left.
  if s.find_entities_filtered{name = "iron-chest", position = {-32.5, -23.5}, radius = 0.6}[1] then
    local plain = s.find_entities_filtered{name = "es-hopper", position = {-32.5, -20.5}, radius = 0.6}[1]
    local mixed = s.find_entities_filtered{name = "es-hopper", position = {-36.5, -20.5}, radius = 0.6}[1]
    local coal = mixed and mixed.get_item_count("coal") or 0
    local ports = s.count_entities_filtered{name = "es-hopper-fluid-port"}
    check("old hoppers lose their fluid port and its fluid; a mixed one keeps its items; no port left",
      plain ~= nil and mixed ~= nil and coal == 5 and ports == 0,
      string.format("fluid-only hopper %s, mixed hopper %s coal %d, ports %d", tostring(plain ~= nil),
        tostring(mixed ~= nil), coal, ports))
  end
  -- (0.70) A world made before keeps its rules: none of the side-effect, early-set or frontier laws (a save
  -- from 0.70 on was made with them: the setup marks an older version).
  if s.find_entities_filtered{name = "small-lamp", position = {-40.5, -20.5}, radius = 0.6}[1] then
    local t = remote.call("empirical-science", "truth")
    check("an older world gains none of 0.70's laws (side effects by class, the early set, the frontier ceiling)",
      not t.side_law and not t.early_law and not t.frontier_law,
      string.format("side %s, early %s, frontier %s", tostring(t.side_law), tostring(t.early_law), tostring(t.frontier_law)))
  end
  check("truth has every current additive and route", remote.call("empirical-science", "truth").traits["es-refined-coal"] ~= nil
    and remote.call("empirical-science", "truth").routes ~= nil)
  table.insert(lines, failed == 0 and "DONE ALL PASSED" or ("DONE " .. failed .. " FAILED"))
  helpers.write_file("es-upgrade-results.txt", table.concat(lines, "\n") .. "\n")
end)
